// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — NFC Handler (Module 10 v2 — Step 10.6, Review 1). * * Toggles NFC on/off. * * ## Behavior (per strategy §"Privacy & Security — NFC") * *  - **Direct toggle** (system app / rooted / ADB-granted WRITE_SECURE_SETTINGS): *    `NfcAdapter.enable` / `disable` via reflection (these are hidden APIs). *  - **Fallback** (regular app): Opens `Settings.ACTION_NFC_SETTINGS` page. * * ## Hardware availability * * Not all devices have NFC. [isAvailable] checks `FEATURE_NFC` via * `PackageManager.hasSystemFeature`. Devices without NFC return * `Result.Failure(Hardware.Unavailable)`. * * ## Idempotent execution (Review 2 Elite 1) * * If NFC is already in the target state, skip the toggle. * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous on/off state. Undo restores the actual previous state. * * ## Resource category * * NFC uses [ResourceCategory.CONNECTIVITY] — it activates the NFC radio, * sequenced with other connectivity ops. * * ## Hardware-heavy * * NFC is **hardware-heavy** (NFC radio + controller) — the executor's thermal * gate will refuse this operation at `THERMAL_SEVERE` (headroom >= 2.5). * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — NFC (Review 1)</a> */class NfcHandler(    private val nfcService: NfcService,) : ReversibleHandler<SystemOperation.SetNfc> {    override val id: String = "nfc"    override val displayName: String = "NFC Control"    override val requiredPermissions: Set<String> = setOf(android.Manifest.permission.NFC)    override val resourceCategory: ResourceCategory = ResourceCategory.CONNECTIVITY    override fun isAvailable(): Boolean = nfcService.isAvailable()    override suspend fun execute(operation: SystemOperation.SetNfc): Result<Unit> {        if (!isAvailable()) {            return Result.Failure(                error = AppError.Hardware.Unavailable("nfc"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        return try {            if (nfcService.canToggleDirectly()) {                // System app / rooted / ADB — direct toggle via reflection.                val success = nfcService.setEnabled(operation.enabled)                if (success) {                    Result.Success(Unit, CorrelationId.generate(), 0)                } else {                    Result.Failure(                        error = AppError.Hardware.Unknown("nfc"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            } else {                // Regular app — open Settings page.                val launched = nfcService.openSettingsPage()                if (launched) {                    Result.Success(                        data = Unit,                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                        warnings = listOf("opened_settings_page"),                    )                } else {                    Result.Failure(                        error = AppError.Hardware.Unsupported("nfc_settings"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            }        } catch (e: UnsupportedOperationException) {            // NFC toggle not supported on this device (even with WRITE_SECURE_SETTINGS).            Timber.tag("NfcHandler").w("NFC toggle not supported", e)            Result.Failure(                error = AppError.Hardware.Unsupported("nfc_toggle", e),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        } catch (t: Throwable) {            Timber.tag("NfcHandler").w("execute failed", t)            Result.Failure(                error = AppError.Hardware.Unknown("nfc", t),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    override suspend fun capturePreState(operation: SystemOperation.SetNfc): Any? {        return try {            NfcPreState(wasEnabled = nfcService.isEnabled())        } catch (t: Throwable) {            Timber.tag("NfcHandler").w("capturePreState failed", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetNfc, preState: Any?) {        if (preState !is NfcPreState) return        try {            if (nfcService.canToggleDirectly()) {                nfcService.setEnabled(preState.wasEnabled)            } else {                Timber.tag("NfcHandler").i("Undo: NFC was ${if (preState.wasEnabled) "on" else "off"} — opening settings for manual restore.")                nfcService.openSettingsPage()            }        } catch (t: Throwable) {            Timber.tag("NfcHandler").w("restorePreState failed", t)        }    }    override suspend fun getCurrentState(): Any? = try {        NfcPreState(wasEnabled = nfcService.isEnabled())    } catch (t: Throwable) { null }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetNfc): Boolean {        return try {            nfcService.isEnabled() == operation.enabled        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetNfc): String =        if (operation.enabled) "NFC turned on" else "NFC turned off"    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is NfcPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"NfcPreState\",\"wasEnabled\":${preState.wasEnabled}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "NfcPreState" -> NfcPreState(wasEnabled = (map["wasEnabled"] as? Boolean) ?: false)            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for NFC (previous on/off). */    data class NfcPreState(val wasEnabled: Boolean)}
